content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: #0f172a;
  color: #f8fafc;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  max-width: 800px;
  padding: 20px;
  gap: 20px;
}

.header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
}

.title {
  font-size: 1.8rem;
  font-weight: 700;
  color: #38bdf8;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  align-items: center;
  background: #1e293b;
  padding: 12px 20px;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.btn {
  background-color: #334155;
  color: #f8fafc;
  border: none;
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:hover {
  background-color: #475569;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: #0284c7;
  color: #ffffff;
}

.btn-primary:hover {
  background-color: #0369a1;
}

.canvas-container {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 3;
  background: #020617;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.3), 0 4px 6px -4px rgba(0, 0, 0, 0.3);
  border: 2px solid #334155;
  cursor: crosshair;
}

.canvas {
  width: 100%;
  height: 100%;
  display: block;
  -webkit-font-smoothing: antialiased;
  image-rendering: -webkit-optimize-contrast;
  image-rendering: crisp-edges;
}

.info-text {
  font-size: 0.9rem;
  color: #94a3b8;
  text-align: center;
}

@media (max-width: 600px) {
  .app-container {
    padding: 10px;
  }

  .title {
    font-size: 1.4rem;
  }

  .controls {
    flex-direction: column;
    width: 100%;
  }

  .btn {
    width: 100%;
  }
}

/**
 * 物理シミュレーションにおけるボールの状態を定義するインターフェース
 */
export interface Ball {
  /** 
   * ボールの一意の識別子。
   * ランダム文字列やUUID等を用いて、シミュレーション内で一意であることが保証される必要があります。
   */
  id: string;
  /** ボールの中心のX座標 (ピクセル) */
  x: number;
  /** ボールの中心のY座標 (ピクセル) */
  y: number;
  /** X方向の速度ベクトル */
  vx: number;
  /** Y方向の速度ベクトル */
  vy: number;
  /** ボールの半径 (ピクセル) */
  radius: number;
  /** ボールの描画色 (CSSカラーコード) */
  color: string;
  /** ボールの質量 (個別物理パラメータ、省略時は半径等から算出または標準値を使用) */
  mass?: number;
  /** ボールの反発係数 (個別物理パラメータ、0〜1の範囲で衝突時の跳ね返りを制御) */
  restitution?: number;
}

import { useState, useEffect, useRef } from 'react';
import { Ball } from './types';

export default function App() {
  const [gravity, setGravity] = useState<number>(0.3);
  const [balls, setBalls] = useState<Ball[]>(() => [
    { id: '1', x: 150, y: 100, vx: 3, vy: 2, radius: 20, color: '#38bdf8' },
    { id: '2', x: 400, y: 150, vx: -2, vy: 4, radius: 25, color: '#f43f5e' },
    { id: '3', x: 600, y: 200, vx: 4, vy: -1, radius: 15, color: '#10b981' },
  ]);

  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const ballsRef = useRef<Ball[]>(balls);
  ballsRef.current = balls;
  const gravityRef = useRef<number>(gravity);
  gravityRef.current = gravity;

  const canvasWidth = 800;
  const canvasHeight = 600;

  const addBall = (x: number, y: number) => {
    const colors = ['#38bdf8', '#f43f5e', '#10b981', '#fbbf24', '#a855f7', '#ec4899'];
    const newBall: Ball = {
      id: crypto.randomUUID(),
      x,
      y,
      vx: (Math.random() - 0.5) * 8,
      vy: (Math.random() - 0.5) * 8,
      radius: Math.floor(Math.random() * 15) + 12,
      color: colors[Math.floor(Math.random() * colors.length)],
    };
    setBalls((prev) => {
      const next = [...prev, newBall];
      ballsRef.current = next;
      return next;
    });
  };

  const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvasWidth / rect.width;
    const scaleY = canvasHeight / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    addBall(x, y);
  };

  const resetBalls = () => {
    const initialBalls: Ball[] = [
      { id: '1', x: 150, y: 100, vx: 3, vy: 2, radius: 20, color: '#38bdf8' },
      { id: '2', x: 400, y: 150, vx: -2, vy: 4, radius: 25, color: '#f43f5e' },
      { id: '3', x: 600, y: 200, vx: 4, vy: -1, radius: 15, color: '#10b981' },
    ];
    setBalls(initialBalls);
    ballsRef.current = initialBalls;
    setGravity(0.3);
  };

  const clearBalls = () => {
    setBalls([]);
    ballsRef.current = [];
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // DPIスケーリングの適用
    const dpr = window.devicePixelRatio || 1;
    canvas.width = canvasWidth * dpr;
    canvas.height = canvasHeight * dpr;
    ctx.scale(dpr, dpr);

    let animationFrameId: number;

    const render = () => {
      ctx.clearRect(0, 0, canvasWidth, canvasHeight);

      // 物理演算の更新
      const updatedBalls = ballsRef.current.map((ball) => {
        let { x, y, vx, vy, radius } = ball;

        // 重力適用
        vy += gravityRef.current;

        // 移動
        x += vx;
        y += vy;

        // 壁との衝突（反発係数と摩擦）
        const restitution = 0.8;
        const friction = 0.99;

        vx *= friction;

        if (x - radius < 0) {
          x = radius;
          vx = -vx * restitution;
        } else if (x + radius > canvasWidth) {
          x = canvasWidth - radius;
          vx = -vx * restitution;
        }

        if (y - radius < 0) {
          y = radius;
          vy = -vy * restitution;
        } else if (y + radius > canvasHeight) {
          y = canvasHeight - radius;
          vy = -vy * restitution;
          vx *= 0.97; // 地面での摩擦
        }

        return { ...ball, x, y, vx, vy };
      });

      // ボール同士の衝突判定
      for (let i = 0; i < updatedBalls.length; i++) {
        for (let j = i + 1; j < updatedBalls.length; j++) {
          const b1 = updatedBalls[i];
          const b2 = updatedBalls[j];
          const dx = b2.x - b1.x;
          const dy = b2.y - b1.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          const minDist = b1.radius + b2.radius;

          if (dist < minDist) {
            const overlap = minDist - dist;
            const nx = dx / (dist || 1);
            const ny = dy / (dist || 1);

            // 位置の補正
            b1.x -= nx * overlap * 0.5;
            b1.y -= ny * overlap * 0.5;
            b2.x += nx * overlap * 0.5;
            b2.y += ny * overlap * 0.5;

            // 速度の交換（弾性衝突）
            const kx = b1.vx - b2.vx;
            const ky = b1.vy - b2.vy;
            const p = 2 * (nx * kx + ny * ky) / 2;

            b1.vx -= p * nx * 0.85;
            b1.vy -= p * ny * 0.85;
            b2.vx += p * nx * 0.85;
            b2.vy += p * ny * 0.85;
          }
        }
      }

      ballsRef.current = updatedBalls;

      // 描画
      updatedBalls.forEach((ball) => {
        ctx.beginPath();
        ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
        ctx.fillStyle = ball.color;
        ctx.shadowColor = ball.color;
        ctx.shadowBlur = 12;
        ctx.fill();
        ctx.closePath();
        ctx.shadowBlur = 0;
      });

      animationFrameId = requestAnimationFrame(render);
    };

    animationFrameId = requestAnimationFrame(render);

    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="app-container">
      <div className="header">
        <h1 className="title">重力物理シミュレーション</h1>
        <p className="info-text">
          画面をクリックすると、クリックした場所に新しいボールが追加されます。
        </p>
      </div>

      <div className="controls">
        <button className="btn btn-primary" onClick={() => addBall(canvasWidth / 2, 50)}>
          ボール追加
        </button>
        <button className="btn" onClick={() => setGravity(0)}>
          無重力
        </button>
        <button className="btn" onClick={() => setGravity(0.3)}>
          標準重力
        </button>
        <button className="btn" onClick={() => setGravity(0.8)}>
          高重力
        </button>
        <button className="btn" onClick={resetBalls}>
          リセット
        </button>
        <button className="btn" onClick={clearBalls}>
          全消去
        </button>
      </div>

      <div className="canvas-container">
        <canvas
          ref={canvasRef}
          width={canvasWidth}
          height={canvasHeight}
          className="canvas"
          onClick={handleCanvasClick}
        />
      </div>

      <div className="info-text">
        現在のボール数: {balls.length} 個
      </div>
    </div>
  );
}
